    if (into) { into.broadphase_tests = host.HEAP32[(out + 0) >> 2]; into.broadphase_rejects = host.HEAP32[(out + 4) >> 2]; into.narrowphase_tests = host.HEAP32[(out + 8) >> 2]; into.narrowphase_hits = host.HEAP32[(out + 12) >> 2]; return into; }
