/**
 * World-space width and height of the laid-out text ((0, 0) until the font loads).
 */
export function wgr_text3d_measure(text, into) {
    const out = record(8);
    host._wgr_text3d_measure(out, text);
    if (into) { into.x = host.HEAPF32[(out + 0) >> 2]; into.y = host.HEAPF32[(out + 4) >> 2]; return into; }
    return { x: host.HEAPF32[(out + 0) >> 2], y: host.HEAPF32[(out + 4) >> 2] };
}

